macro.command:
if (workflow.aborted || workflow.activity.type !== "attack") return;
const pass = args[0]?.macroPass;
if (!["postDamageRoll", "postActiveEffects"].includes(pass)) return;
const targets = Array.from(workflow.targets);
if (targets.length !== 1) {
  return ui.notifications.warn("混乱箭：每次攻击只能选择一个目标。");
}
const current = targets[0];
const dialogs = game.modules.get("dnd5e_classpack").api.dialogUtils;
const types = {
  1: { key: "acid", label: "强酸" },
  2: { key: "cold", label: "寒冷" },
  3: { key: "fire", label: "火焰" },
  4: { key: "force", label: "力场" },
  5: { key: "lightning", label: "闪电" },
  6: { key: "poison", label: "毒素" },
  7: { key: "psychic", label: "心灵" },
  8: { key: "thunder", label: "雷鸣" }
};

if (pass === "postDamageRoll") {
  if (!workflow.hitTargets?.size || workflow._chaosBoltDamageDone) return;
  const rolls = workflow.damageRolls;
  const d8 = rolls.flatMap(roll => roll.dice)
    .filter(die => die.faces === 8)
    .flatMap(die => die.results.filter(result =>
      result.active !== false && !result.discarded && !result.rerolled
    ).map(result => result.result)).slice(0, 2);
  if (d8.length !== 2 || !d8.every(value => types[value])) {
    return ui.notifications.warn("混乱箭：无法读取两颗 d8，请检查攻击活动的伤害配置。");
  }

  const choices = [...new Set(d8)];
  const selected = choices.length === 1 ? types[choices[0]].key :
    await dialogs.selectDamageType(
      choices.map(value => types[value].key),
      "混乱箭：选择伤害类型",
      `<p>两颗 d8：${d8.map(value => `${value}（${types[value].label}）`).join("、")}。选择本次全部伤害的类型。</p>`
    );
  // Closing the damage-type dialog uses the first eligible type.
  const type = selected || types[choices[0]].key;
  for (const roll of rolls) {
    roll.options.type = type;
    roll.options.types = [type];
    for (const die of roll.dice) die.options.flavor = type;
    roll.resetFormula();
  }
  workflow.defaultDamageType = type;
  await workflow.setDamageRolls(rolls);
  workflow._chaosBoltDamageDone = true;
  workflow._chaosBoltCanLeap = d8[0] === d8[1];
  return;
}

if (!workflow.hitTargets?.size || !workflow._chaosBoltCanLeap
  || workflow._chaosBoltLeapQueued) return;
const visited = new Set(workflow.workflowOptions.chaosBoltVisited ?? []);
visited.add(current.document.uuid);
const distance = dnd5e.utils.convertLength(30, "ft", canvas.scene.grid.units, { strict: false });
const candidates = MidiQOL.findNearby(null, current, distance, {
  includeToken: false,
  includeIncapacitated: true,
  canSee: false,
  isSeen: false
}).filter(token => ["character", "npc"].includes(token.actor?.type)
  && !visited.has(token.document.uuid));
if (!candidates.length) {
  return ui.notifications.info("混乱箭：30 尺内没有尚未被本次施法选中过的生物。");
}

const [next] = await dialogs.selectTargetDialog(
  "混乱箭：选择跳跃目标",
  "<p>两颗 d8 相同。选择 30 尺内的新目标；取消或关闭窗口可结束跳跃。</p>",
  candidates,
  { type: "one", skipDeadAndUnconscious: false }
);
if (!next) return;
visited.add(next.document.uuid);

// A leap is measured from the previous target, not the original caster.
// Temporary item clone removes the original caster-to-target range check.
// Only this clone changes; the character's original spell is not edited.
const path = `system.activities.${workflow.activity.id}`;
const nextItem = macroItem.clone({
  [`${path}.range.override`]: true,
  [`${path}.range.value`]: null,
  [`${path}.range.long`]: null,
  [`${path}.range.units`]: "spec",
  [`${path}.activation.type`]: "",
  [`${path}.otherActivityId`]: "none",
  [`${path}.midiProperties.triggeredActivityId`]: ""
}, { keepId: true });
const nextActivity = nextItem.system.activities.get(workflow.activity.id);
const baseLevel = Number(macroItem.system.level) || 1;
const castLevel = Math.max(baseLevel, Number(workflow.spellLevel) || baseLevel);
const usage = {
  consume: { resources: false, spellSlot: false, action: false },
  create: { measuredTemplate: false },
  scaling: castLevel - baseLevel,
  midiOptions: {
    spellLevel: castLevel,
    targetsToUse: new Set([next]),
    ignoreUserTargets: true,
    isCritical: false,
    workflowOptions: {
      targetConfirmation: "none",
      notReaction: true,
      notBonusAction: true,
      chaosBoltVisited: Array.from(visited)
    }
  }
};

// Launch after the current workflow cleans up, avoiding nested chain timeouts
// and letting Midi restore the previous workflow's target selection first.
workflow._chaosBoltLeapQueued = true;
const hookName = `midi-qol.postCleanup.${workflow.activity.uuid}`;
const hookId = Hooks.on(hookName, finished => {
  if (finished.id !== workflow.id) return;
  Hooks.off(hookName, hookId);
  if (finished.aborted) return;
  void MidiQOL.completeActivityUse(nextActivity, usage,
    { configure: false }, { create: true }).catch(error => {
    console.error("混乱箭跳跃失败", error);
    ui.notifications.error(`混乱箭跳跃失败：${error.message}`);
  });
});
